package local.proskurnin.preview;
import android.app.*;import android.content.*;import android.content.pm.*;import android.database.Cursor;import android.net.Uri;import android.os.CancellationSignal;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Public Android TV search contract. No account databases, root, guessed IDs or intent deserialization. */
final class CinemaSearch {
 static final Map<String,ThreadPoolExecutor> workers=new HashMap<>();
 static synchronized ThreadPoolExecutor worker(String pkg){ThreadPoolExecutor w=workers.get(pkg);if(w==null){w=new ThreadPoolExecutor(0,1,30,TimeUnit.SECONDS,new SynchronousQueue<Runnable>(),new ThreadPoolExecutor.AbortPolicy());workers.put(pkg,w);}return w;}
 static final LinkedHashMap<String,Result> cache=new LinkedHashMap<>();static final HashMap<String,Long> times=new HashMap<>();
 static final class Result {final ArrayList<Match> matches=new ArrayList<>();String status="unsupported";}
 static final class Match {String title,year,source="";Intent intent;Match(String t,String y,Intent i){title=t;year=y;intent=i;}}
 static boolean known(String pkg){for(String p:MovieActivity.PACKAGES)if(p.equals(pkg))return true;return false;}
 static ArrayList<ComponentName> activities(Context c,String pkg){ArrayList<ComponentName> out=new ArrayList<>();if(!known(pkg))return out;for(ResolveInfo r:c.getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_SEARCH).setPackage(pkg),0)){ActivityInfo a=r.activityInfo;if(a!=null&&a.exported&&a.enabled&&pkg.equals(a.packageName)&&(a.permission==null||c.checkSelfPermission(a.permission)==PackageManager.PERMISSION_GRANTED))out.add(new ComponentName(pkg,a.name));}return out;}
 static Intent search(Context c,String pkg,String title){if("com.lazycatsoftware.lmd".equals(pkg))return null;ArrayList<ComponentName> list=activities(c,pkg);if(list.isEmpty())return null;return new Intent(Intent.ACTION_SEARCH).setComponent(list.get(0)).putExtra(SearchManager.QUERY,title);}
 static String get(Cursor c,String name){int i=c.getColumnIndex(name);return i<0||c.isNull(i)?"":c.getString(i);}
 static ArrayList<Match> find(Context c,String pkg,JSONObject movie,CancellationSignal parent){return inspect(c,pkg,movie,parent).matches;}
 static Result inspect(Context context,String pkg,JSONObject movie,CancellationSignal parent){
  Result fallback=new Result();if(!known(pkg))return fallback;String key=pkg+"|"+movie.optInt("id")+"|"+movie.optString("title")+"|"+movie.optString("year");synchronized(cache){Long at=times.get(key);if(at!=null&&android.os.SystemClock.elapsedRealtime()-at<300000&&cache.containsKey(key))return cache.get(key);}CancellationSignal query=new CancellationSignal();parent.setOnCancelListener(()->query.cancel());Future<Result> future=null;
  try{parent.throwIfCanceled();future=worker(pkg).submit(()->query(context,pkg,movie,query));Result found=future.get(pkg.equals("com.lazycatsoftware.lmd")?75:20,TimeUnit.SECONDS);if(!found.matches.isEmpty())synchronized(cache){while(cache.size()>=32){String first=cache.keySet().iterator().next();cache.remove(first);times.remove(first);}cache.put(key,found);times.put(key,android.os.SystemClock.elapsedRealtime());}return found;}catch(TimeoutException e){fallback.status="timeout";}catch(RejectedExecutionException e){fallback.status="busy";}catch(Exception e){fallback.status=parent.isCanceled()?"cancelled":"error";}finally{query.cancel();if(future!=null)future.cancel(true);parent.setOnCancelListener(null);}return fallback;
 }
 static Result query(Context c,String pkg,JSONObject movie,CancellationSignal signal){
  Result result=new Result();ArrayList<Match> out=result.matches;SearchManager manager=(SearchManager)c.getSystemService(Context.SEARCH_SERVICE);Set<String> seen=new HashSet<>();
  for(ComponentName component:activities(c,pkg)){signal.throwIfCanceled();SearchableInfo info=manager.getSearchableInfo(component);if(info==null||info.getSuggestAuthority()==null)continue;String authority=info.getSuggestAuthority();ProviderInfo provider=c.getPackageManager().resolveContentProvider(authority,0);if(provider==null&&pkg.equals("mobi.zona")){ProviderInfo actual=c.getPackageManager().resolveContentProvider("mobi.zona.TvSearchProvider",0);if(actual!=null&&actual.name.equals("ru.zona.app.android.tv.search.TvSearchProvider")){provider=actual;authority=actual.authority;}}if(provider==null||!pkg.equals(provider.packageName))continue;if(!provider.exported){result.status="restricted";continue;}result.status="no_matches";
   Uri.Builder uri=new Uri.Builder().scheme("content").authority(authority);if(info.getSuggestPath()!=null)uri.appendEncodedPath(info.getSuggestPath());uri.appendPath(SearchManager.SUGGEST_URI_PATH_QUERY);String selection=info.getSuggestSelection();String[] args=null;if(pkg.equals("mobi.zona")||pkg.equals("ru.kinopoisk.tv")){selection="?";args=new String[]{movie.optString("title")};}else if(selection==null)uri.appendPath(movie.optString("title"));else args=new String[]{movie.optString("title")};uri.appendQueryParameter("limit","20");
   try(Cursor rows=c.getContentResolver().query(uri.build(),null,selection,args,null,signal)){if(rows==null)continue;int count=0;while(count++<30&&rows.moveToNext()){signal.throwIfCanceled();String title=get(rows,SearchManager.SUGGEST_COLUMN_TEXT_1),year=get(rows,"suggest_production_year");if(!CinemaMatch.title(movie.optString("title"),movie.optString("original_title"),title))continue;if(!year.matches("(?:18|19|20|21)[0-9]{2}"))year=CinemaMatch.year(get(rows,SearchManager.SUGGEST_COLUMN_TEXT_2));if(year.isEmpty())year=CinemaMatch.year(title);String expected=movie.optString("year");if(!year.isEmpty()&&!expected.isEmpty()&&!year.equals(expected))continue;
    String action=get(rows,SearchManager.SUGGEST_COLUMN_INTENT_ACTION);if(action.isEmpty())action=info.getSuggestIntentAction();if(action==null)action=Intent.ACTION_SEARCH;if(!action.equals(Intent.ACTION_VIEW)&&!action.equals(Intent.ACTION_SEARCH))continue;
    String data=get(rows,SearchManager.SUGGEST_COLUMN_INTENT_DATA);if(data.isEmpty())data=info.getSuggestIntentData();String id=get(rows,SearchManager.SUGGEST_COLUMN_INTENT_DATA_ID);if(data!=null&&!id.isEmpty())data+="/"+Uri.encode(id);if(data==null||data.isEmpty()||data.length()>8192)continue;if(pkg.equals("mobi.zona"))data=CinemaMatch.zonaLink(data);Uri target=Uri.parse(data);String scheme=target.getScheme();if((scheme==null&&!(pkg.equals("com.lazycatsoftware.lmd")&&CinemaMatch.lazyPayload(data)))||Arrays.asList("file","intent","javascript","data").contains(scheme))continue;
    Intent intent=new Intent(action,target).setComponent(component);String extra=get(rows,SearchManager.SUGGEST_COLUMN_INTENT_EXTRA_DATA);if(extra.length()>2000)continue;if(!extra.isEmpty())intent.putExtra(SearchManager.EXTRA_DATA_KEY,extra);String query=get(rows,SearchManager.SUGGEST_COLUMN_QUERY);if(!query.isEmpty())intent.putExtra(SearchManager.QUERY,query.substring(0,Math.min(160,query.length())));if(seen.add(data+"\n"+extra)){Match match=new Match(title,year,intent);if(pkg.equals("com.lazycatsoftware.lmd")){String label=get(rows,SearchManager.SUGGEST_COLUMN_TEXT_2);match.source=label.substring(0,Math.min(60,label.length()));}out.add(match);}if(out.size()>=8){result.status="found";return result;}
   }}catch(SecurityException e){result.status="restricted";}catch(Exception e){result.status="error";}
  }if(!out.isEmpty())result.status="found";return result;
 }
}
